join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P303', 'P304', 'P305', 'P306', 'P307', 'P308', 'P309', 'P310', 'P311', 'P312', 'P313', 'P314', 'P315', 'P316', 'P317', 'P318', 'P319', 'P320', 'P321', 'P322', 'P323', 'P324', 'P325', 'P326', 'P327')) <> 25 then
    raise exception 'a character of the thirteenth batch has no kit';
  end if;
end $$;
